import numpy as np
import pandas as pd
from scipy import stats
from statsmodels.stats.multitest import multipletests
import krippendorff

# 1. Load the Long_Format sheet generated by combine_surveys.py
MASTER_LOG_PATH = r"C:\Users\User\Downloads\chipRAG_master.xlsx"
df = pd.read_excel(MASTER_LOG_PATH, sheet_name="Long_Format")

models = sorted(df["Model"].unique())
metrics = sorted(df["Metric"].unique())

# ==========================================
# 1. DESCRIPTIVE STATISTICS
# ==========================================
print("=" * 60)
print("1. DESCRIPTIVE STATISTICS (Mean, SD, Median)")
print("=" * 60)
desc_stats = df.groupby(["Model", "Metric"])["Score"].agg(
    Mean="mean",
    SD="std",
    Median="median",
    Count="count"
).round(3)
print(desc_stats)

# ==========================================
# 2. FRIEDMAN TEST
# ==========================================
print("\n" + "=" * 60)
print("2. FRIEDMAN TEST (Overall Differences Across Models)")
print("=" * 60)

# Aggregate multiple submissions per question to get a single score per Model x Question pair
df_agg = df.groupby(["Model", "Question_ID", "Metric"])["Score"].mean().reset_index()

significant_metrics = []
for metric in metrics:
    metric_df = df_agg[df_agg["Metric"] == metric]
    pivot_df = metric_df.pivot(index="Question_ID", columns="Model", values="Score").dropna()
    
    if pivot_df.shape[1] == len(models):
        groups = [pivot_df[m].values for m in models]
        stat, p_val = stats.friedmanchisquare(*groups)
        sig = "SIGNIFICANT (p < 0.05)" if p_val < 0.05 else "NOT SIGNIFICANT"
        print(f"{metric:25s}: Stat = {stat:6.2f} | p-value = {p_val:.4e} | {sig}")
        if p_val < 0.05:
            significant_metrics.append(metric)
    else:
        print(f"{metric:25s}: Skipped (incomplete question data across models)")

# ==========================================
# 3. WILCOXON SIGNED-RANK TEST & EFFECT SIZE
# ==========================================
print("\n" + "=" * 60)
print("3. POST-HOC WILCOXON SIGNED-RANK TEST & EFFECT SIZE")
print("=" * 60)

for metric in significant_metrics:
    print(f"\n--- Metric: {metric} ---")
    metric_df = df_agg[df_agg["Metric"] == metric]
    pivot_df = metric_df.pivot(index="Question_ID", columns="Model", values="Score").dropna()
    
    pairwise_records = []
    for i in range(len(models)):
        for j in range(i + 1, len(models)):
            m1, m2 = models[i], models[j]
            x, y = pivot_df[m1].values, pivot_df[m2].values
            
            if not np.array_equal(x, y):
                stat, p_val = stats.wilcoxon(x, y)
                n_pairs = len(x)
                p_safe = max(min(p_val, 0.999999), 1e-15)
                z_stat = stats.norm.ppf(1 - p_safe / 2)
                r_effect = z_stat / np.sqrt(n_pairs)
                
                pairwise_records.append({
                    "Comparison": f"{m1} vs {m2}",
                    "p_value": p_val,
                    "Effect_Size_r": round(r_effect, 3)
                })
                
    if pairwise_records:
        pw_df = pd.DataFrame(pairwise_records)
        reject, p_corr, _, _ = multipletests(pw_df["p_value"], alpha=0.05, method="holm")
        pw_df["p_corrected_holm"] = p_corr
        pw_df["Significant"] = reject
        
        sig_pairs = pw_df[pw_df["Significant"] == True]
        if not sig_pairs.empty:
            print(sig_pairs.to_string(index=False))
        else:
            print("No pairwise differences remained significant after Holm correction.")

# ==========================================
# 4. KRIPPENDORFF'S ALPHA
# ==========================================
print("\n" + "=" * 60)
print("4. KRIPPENDORFF'S ALPHA (Inter-Rater Agreement)")
print("=" * 60)

for metric in metrics:
    sub_df = df[df["Metric"] == metric]
    # Matrix: Rows = Submission/Evaluator, Columns = (Model, Question_ID)
    reliability_df = sub_df.pivot_table(
        index="Submission_ID", 
        columns=["Model", "Question_ID"], 
        values="Score"
    )
    matrix = reliability_df.values
    
    try:
        alpha = krippendorff.alpha(reliability_data=matrix, level_of_measurement="ordinal")
        print(f"{metric:25s}: Alpha = {alpha:6.3f}")
    except Exception as e:
        print(f"{metric:25s}: Could not compute Alpha ({e})")